package com.healthwise.questionnaire.service;
import com.healthwise.exception.ResourceNotFoundException;import com.healthwise.questionnaire.dto.QuestionnaireDtos.*;import com.healthwise.questionnaire.entity.Questionnaire;import com.healthwise.questionnaire.repository.QuestionnaireRepository;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;
@Service public class QuestionnaireService{private final QuestionnaireRepository repo;public QuestionnaireService(QuestionnaireRepository r){repo=r;}private Response dto(Questionnaire q){return new Response(q.getId(),q.getSubmittedAt(),q.getQuestionnaire());}public Response save(String user,Create d){Questionnaire q=new Questionnaire();q.setUserId(user);q.setSubmittedAt(Instant.now());q.setQuestionnaire(Map.copyOf(d.questionnaire()));return dto(repo.save(q));}public List<Response> list(String user){return repo.findByUserIdOrderBySubmittedAtDesc(user).stream().map(this::dto).toList();}public Response get(String user,String id){Questionnaire q=repo.findById(id).filter(x->x.getUserId().equals(user)).orElseThrow(()->new ResourceNotFoundException("Questionnaire not found"));return dto(q);}}
